#!/usr/bin/env node
/**
 * Generate the winget and scoop drafts from `brand.json`.
 *
 *   node packaging/channel-manifests.mjs
 *   node packaging/channel-manifests.mjs --check
 *
 * Both files are drafts: they point at the release assets the tag workflow
 * publishes, and the hashes stay as 64 zeroes until a real `SHA256SUMS` exists
 * in `dist/release` or `dist/windows`. `--check` regenerates in memory and
 * fails when the committed draft drifts from `brand.json`.
 *
 * Names, ids, and URLs come from `brand.json` and the Tauri config. Never edit
 * the generated files by hand.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');

function readJson(relativePath) {
  return JSON.parse(fs.readFileSync(path.join(repoRoot, relativePath), 'utf8'));
}

function readTextIfExists(relativePath) {
  const absolute = path.join(repoRoot, relativePath);
  return fs.existsSync(absolute) ? fs.readFileSync(absolute, 'utf8') : null;
}

const brand = readJson('brand.json');
const packaging = readJson('packaging/manifest.json');
const tauri = readJson('app/src-tauri/tauri.conf.json');
const version = tauri.version;
const tag = `v${version}`;
const release = `${brand.repository}/releases/download/${tag}`;
const product = brand.name;

const cliArchive = `${brand.crates.cli}-x86_64-pc-windows-msvc.zip`;
const nsis = `${product}_${version}_x64-setup.exe`;
const msi = `${product}_${version}_x64_en-US.msi`;

function loadChecksums() {
  for (const relativePath of ['dist/release/SHA256SUMS', 'dist/windows/SHA256SUMS']) {
    const text = readTextIfExists(relativePath);
    if (!text) continue;
    const map = new Map();
    for (const line of text.split(/\r?\n/)) {
      const match = /^([0-9a-f]{64})\s+\*?(.+)$/i.exec(line.trim());
      if (match) map.set(path.basename(match[2]), match[1].toLowerCase());
    }
    return map;
  }
  return new Map();
}

const sums = loadChecksums();
const placeholder = '0'.repeat(64);
const hash = (name) => sums.get(name) ?? placeholder;

const winget = `# Generated by packaging/channel-manifests.mjs from brand.json.
# Draft only. Replace the zero hashes with the SHA256SUMS values from the
# published release, then run \`winget validate\` before opening a PR to
# microsoft/winget-pkgs.
PackageIdentifier: ${packaging.channels.winget}
PackageVersion: ${version}
PackageLocale: en-US
Publisher: Pandu contributors
PublisherUrl: ${brand.repository}
PackageName: ${product}
PackageUrl: ${brand.repository}
License: ${packaging.license}
LicenseUrl: ${brand.repository}/blob/main/LICENSE
ShortDescription: ${brand.tagline}
Description: ${tauri.bundle.longDescription}
Moniker: ${brand.cli.command}
Tags:
  - ai
  - developer-tools
  - observability
  - privacy
Installers:
  - Architecture: x64
    InstallerType: nullsoft
    InstallerUrl: ${release}/${nsis}
    InstallerSha256: ${hash(nsis)}
    Scope: user
    InstallerSwitches:
      Silent: /S
      SilentWithProgress: /S
    UpgradeBehavior: install
  - Architecture: x64
    InstallerType: wix
    InstallerUrl: ${release}/${msi}
    InstallerSha256: ${hash(msi)}
    Scope: machine
    UpgradeBehavior: install
ManifestType: singleton
ManifestVersion: 1.6.0
`;

const scoop = {
  $schema: 'https://raw.githubusercontent.com/ScoopInstaller/Scoop/master/schema.json',
  version,
  description: brand.tagline,
  homepage: brand.repository,
  license: packaging.license,
  notes: [
    `Draft generated from brand.json by packaging/channel-manifests.mjs.`,
    `Replace the zero hash with the published SHA256SUMS value for ${cliArchive}.`,
  ],
  architecture: {
    '64bit': {
      url: `${release}/${cliArchive}`,
      hash: hash(cliArchive),
      extract_dir: `${brand.crates.cli}-x86_64-pc-windows-msvc`,
    },
  },
  bin: `${brand.cli.command}.exe`,
  checkver: { github: brand.repository },
  autoupdate: {
    architecture: {
      '64bit': {
        url: `${brand.repository}/releases/download/v$version/${brand.crates.cli}-x86_64-pc-windows-msvc.zip`,
      },
    },
  },
};

const outputs = [
  ['packaging/winget/ganddtn40.Pandu.yaml', winget],
  ['packaging/scoop/pandu.json', `${JSON.stringify(scoop, null, 2)}\n`],
];

let drifted = 0;
for (const [relativePath, content] of outputs) {
  const current = readTextIfExists(relativePath);
  if (check) {
    if (current !== content) {
      console.error(`drift: ${relativePath} does not match brand.json.`);
      drifted += 1;
    }
    continue;
  }
  fs.mkdirSync(path.dirname(path.join(repoRoot, relativePath)), { recursive: true });
  if (current !== content) {
    fs.writeFileSync(path.join(repoRoot, relativePath), content, 'utf8');
    console.log(`wrote ${relativePath}`);
  } else {
    console.log(`unchanged ${relativePath}`);
  }
}

if (check) {
  if (drifted > 0) process.exit(1);
  console.log('channel manifests match brand.json.');
}
